# policy: orders-app
path "secret/data/orders/*" {
  capabilities = ["read"]
}
# vault kv get secret/orders/db   → allowed
# vault kv get secret/payments/db → permission denied

apiVersion: external-secrets.io/v1beta1
kind: ExternalSecret
metadata: { name: orders-db }
spec:
  refreshInterval: 1h
  secretStoreRef: { name: aws-sm, kind: ClusterSecretStore }
  target: { name: orders-db }
  data:
    - secretKey: password
      remoteRef: { key: prod/orders/db, property: password }
